arguments.file_text:
@using sv_38a3a09d06384347b6f087173d38f654.Services
@inject IJSRuntime JS
@implements IAsyncDisposable

<div class="message-area">
    <div class="area-header">
        <h6># @ChannelName</h6>
        <span class="area-description">@ChannelDescription</span>
    </div>

    <div class="message-list" @ref="messageListRef">
        @if (HasMoreMessages)
        {
            <div class="load-more">
                <button class="load-more-btn" @onclick="OnLoadMore" disabled="@IsLoadingMore">
                    @(IsLoadingMore ? "Loading…" : "Load older messages")
                </button>
            </div>
        }

        @foreach (var msg in Messages)
        {
            <MessageItem Message="msg"
                         ShowThreadLink="msg.ReplyToId is null"
                         ReplyCount="GetReplyCount(msg.Id)"
                         OnReplyClick="() => OnOpenThread.InvokeAsync(msg.Id)"
                         OnReact="emoji => OnReact.InvokeAsync((msg.Id, emoji))" />
        }
        <div @ref="bottomAnchor"></div>
    </div>

    <MessageInput Placeholder="@($"Message #{ChannelName}")"
                  ButtonText="Send"
                  OnSend="OnSendMessage" />
</div>

@code {
    private ElementReference messageListRef;
    private ElementReference bottomAnchor;
    private IJSObjectReference? jsModule;
    private bool shouldScrollToBottom = true;

    [Parameter, EditorRequired] public string ChannelName { get; set; } = "";
    [Parameter] public string ChannelDescription { get; set; } = "";
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public bool HasMoreMessages { get; set; }
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }

    private int GetReplyCount(int messageId)
    {
        return ThreadSummaries.TryGetValue(messageId, out var summary) ? summary.ReplyCount : 0;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            jsModule = await JS.InvokeAsync<IJSObjectReference>("import",
                "./_content/sv-38a3a09d06384347b6f087173d38f654/Components/Chat/MessageArea.razor.js");
        }

        if (shouldScrollToBottom && jsModule is not null)
        {
            await jsModule.InvokeVoidAsync("scrollToBottom", messageListRef);
            shouldScrollToBottom = false;
        }
    }

    public void ScrollToBottom() => shouldScrollToBottom = true;

    public async ValueTask DisposeAsync()
    {
        if (jsModule is not null)
        {
            await jsModule.DisposeAsync();
        }
    }
}

export function scrollToBottom(element) {
    if (element) {
        element.scrollTop = element.scrollHeight;
    }
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #fff;
    overflow: hidden;
}

.area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #e0e0e0;
    flex-shrink: 0;
}

.area-header h6 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #2c2f33;
}

.area-description {
    font-size: 0.8rem;
    color: #777;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.load-more {
    text-align: center;
    padding: 8px;
}

.load-more-btn {
    background: none;
    border: 1px solid #ddd;
    border-radius: 6px;
    padding: 6px 16px;
    font-size: 0.8rem;
    color: #5865f2;
    cursor: pointer;
    transition: background 0.15s;
}

.load-more-btn:hover:not(:disabled) {
    background: #f0f0ff;
}

.load-more-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

@using sv_38a3a09d06384347b6f087173d38f654.Services

<aside class="thread-panel">
    <div class="thread-header">
        <h6>Thread</h6>
        <button class="close-btn" @onclick="OnClose" title="Close thread">&times;</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root">
            <MessageItem Message="RootMessage" ShowThreadLink="false" OnReact="OnReact" />
        </div>

        <div class="thread-divider">
            <span>@ThreadMessages.Count @(ThreadMessages.Count == 1 ? "reply" : "replies")</span>
        </div>

        <div class="thread-replies">
            @foreach (var reply in ThreadMessages)
            {
                <MessageItem Message="reply" ShowThreadLink="false" OnReact="OnReact" />
            }
        </div>

        <MessageInput Placeholder="Reply…"
                      ButtonText="Reply"
                      OnSend="OnSendReply" />
    }
</aside>

