+                         IsLoadingMore="isLoadingMore"
+                         OnLoadMore="LoadOlderMessages"
+                         OnOpenThread="OpenThread"
+                         OnReact="HandleReaction"
+                         OnSendMessage="SendMessage" />
+        }
+        else
+        {
+            <div class="no-channel">
+                <p>Select a channel to start chatting</p>
+            </div>
+        }
+    </div>
+
+    @if (isThreadOpen && threadRootMessage is not null)
+    {
+        <div class="chat-thread">
+            <ThreadPanel RootMessage="threadRootMessage"
+                         ThreadMessages="threadMessages"
+                         OnClose="CloseThread"
+                         OnSendReply="SendThreadReply"
+                         OnReact="HandleReaction" />
+        </div>
+    }
+</div>
+
+@code {
+    private const int PageSize = 30;
+
+    private List<Channel> channels = [];
+    private int? selectedChannelId;
+    private Channel? selectedChannel;
+    private List<Message> messages = [];
+    private Dictionary<int, ThreadSummary> threadSummaries = [];
+    private int skip;
+    private bool hasMoreMessages = true;
+    private bool isLoadingMore;
+
+    private bool isThreadOpen;
+    private int? threadRootId;
+    private Message? threadRootMessage;
+    private List<Message> threadMessages = [];
+
+    private MessageArea? messageAreaRef;
+
+    protected override async Task OnInitializedAsync()
+    {
+        channels = await ChatService.GetChannelsAsync();
+        if (channels.Count > 0)
+        {
+            await SelectChannel(channels[0].Id);
+        }
+    }
+
+    private async Task SelectChannel(int channelId)
+    {
+        if (selectedChannelId == channelId) return;
+
+        selectedChannelId = channelId;
+        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
+        skip = 0;
+        hasMoreMessages = true;
+        messages = [];
+        threadSummaries = [];
+        CloseThread();
+
+        var loaded = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
+        messages = loaded;
+        skip = loaded.Count;
+        hasMoreMessages = loaded.Count >= PageSize;
+
+        BuildThreadSummaries();
+
+        await ChatService.MarkChannelReadAsync(channelId);
+        RefreshChannelUnread(channelId);
+
+        messageAreaRef?.ScrollToBottom();
+    }
+
+    private async Task LoadOlderMessages()
+    {
+        if (selectedChannelId is null || isLoadingMore) return;
+
+        isLoadingMore = true;
+        var older = await ChatService.GetMessagesAsync(selectedChannelId.Value, skip, PageSize);
+        if (older.Count > 0)
+        {
+            messages.InsertRange(0, older);
+            skip += older.Count;
+            BuildThreadSummaries();
+        }
+        hasMoreMessages = older.Count >= PageSize;
+        isLoadingMore = false;
+    }
+
+    private async Task SendMessage(string content)
+    {
+        if (selectedChannelId is null) return;
+
+        var msg = await ChatService.SendMessageAsync(selectedChannelId.Value, content, null);
+        messages.Add(msg);
+        skip++;
+        messageAreaRef?.ScrollToBottom();
+        StateHasChanged();
+    }
+
+    private async Task OpenThread(int rootMessageId)
+    {
+        threadRootId = rootMessageId;
+        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootMessageId);
+        threadMessages = await ChatService.GetThreadAsync(rootMessageId);
+        isThreadOpen = true;
+    }
+
+    private void CloseThread()
+    {
+        isThreadOpen = false;
+        threadRootId = null;
+        threadRootMessage = null;
+        threadMessages = [];
+    }
+
+    private async Task SendThreadReply(string content)
+    {
+        if (selectedChannelId is null || threadRootId is null) return;
+
+        var reply = await ChatService.SendMessageAsync(selectedChannelId.Value, content, threadRootId.Value);
+        threadMessages.Add(reply);
+        UpdateThreadSummary(threadRootId.Value);
+    }
+
+    private async Task HandleReaction((int MessageId, string Emoji) args)
+    {
+        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
+
+        // Optimistically update the reaction in the local message list
+        UpdateReactionLocally(messages, args.MessageId, args.Emoji);
+        UpdateReactionLocally(threadMessages, args.MessageId, args.Emoji);
+    }
+
+    private static void UpdateReactionLocally(List<Message> messageList, int messageId, string emoji)
+    {
+        var idx = messageList.FindIndex(m => m.Id == messageId);
+        if (idx < 0) return;
+
+        var msg = messageList[idx];
+        var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
+        if (existing is not null)
+        {
+            if (!existing.Users.Contains("You"))
+            {
+                existing.Users.Add("You");
+            }
+        }
+        else
+        {
+            msg.Reactions.Add(new Reaction(emoji, ["You"]));
+        }
+    }
+
+    private void BuildThreadSummaries()
+    {
+        threadSummaries = messages
+            .Where(m => m.ReplyToId is not null)
+            .GroupBy(m => m.ReplyToId!.Value)
+            .ToDictionary(
+                g => g.Key,
+                g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)));
+    }
+
+    private void UpdateThreadSummary(int rootMessageId)
+    {
+        if (threadSummaries.TryGetValue(rootMessageId, out var existing))
+        {
+            threadSummaries[rootMessageId] = existing with
+            {
+                ReplyCount = existing.ReplyCount + 1,
+                LastReplyAt = DateTime.UtcNow
+            };
+        }
+        else
+        {
+            threadSummaries[rootMessageId] = new ThreadSummary(rootMessageId, 1, DateTime.UtcNow);
+        }
+    }
+
+    private void RefreshChannelUnread(int channelId)
+    {
+        var idx = channels.FindIndex(c => c.Id == channelId);
+        if (idx >= 0)
+        {
+            channels[idx] = channels[idx] with { UnreadCount = 0 };
+        }
+    }
+}
+

